CREATE TABLE IF NOT EXISTS "trade_order"
(
    "id"                      bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no"                      varchar  NOT NULL,
    "type"                    int      NOT NULL,
    "terminal"                int      NOT NULL,
    "user_id"                 bigint   NOT NULL,
    "user_ip"                 varchar  NOT NULL,
    "user_remark"             varchar,
    "status"                  int      NOT NULL,
    "product_count"           int      NOT NULL,
    "cancel_type"             int,
    "remark"                  varchar,
    "comment_status"          boolean,
    "brokerage_user_id"       bigint,
    "pay_status"              bit      NOT NULL,
    "pay_time"                datetime,
    "finish_time"             datetime,
    "cancel_time"             datetime,
    "total_price"             int      NULL,
    "order_price"             int      NULL,
    "discount_price"          int      NOT NULL,
    "delivery_price"          int      NOT NULL,
    "adjust_price"            int      NOT NULL,
    "pay_price"               int      NOT NULL,
    "delivery_type"           int      NOT NULL,
    "pay_order_id"            bigint,
    "pay_channel_code"        varchar,
    "delivery_template_id"    bigint,
    "logistics_id"            bigint,
    "logistics_no"            varchar,
    "delivery_time"           datetime,
    "receive_time"            datetime,
    "receiver_name"           varchar  NOT NULL,
    "receiver_mobile"         varchar  NOT NULL,
    "receiver_area_id"        int      NOT NULL,
    "receiver_post_code"      int,
    "receiver_detail_address" varchar  NOT NULL,
    "pick_up_store_id"        long     NULL,
    "pick_up_verify_code"     varchar  NULL,
    "refund_status"           int      NULL,
    "refund_price"            int      NULL,
    "after_sale_status"       int      NULL,
    "coupon_id"               bigint   NOT NULL,
    "coupon_price"            int      NOT NULL,
    "use_point"               int      NULL,
    "point_price"             int      NOT NULL,
    "give_point"              int      NULL,
    "refund_point"            int      NULL,
    "vip_price"               int      NULL,
    "give_coupons_map"        varchar  NULL,
    "seckill_activity_id"     long     NULL,
    "bargain_activity_id"     long     NULL,
    "bargain_record_id"       long     NULL,
    "combination_activity_id" long     NULL,
    "combination_head_id"     long     NULL,
    "combination_record_id"   long     NULL,
    -- ⚠️ 下面三列是 006 补的：`TradeOrderDO` 声明了它们，而这份 H2 建表漏了。
    --    该模块此前**一个测试都没有**，所以只 insert（只列非空字段）时看不出来 ——
    --    直到有测试去 `selectById` 订单，MyBatis-Plus 会把 DO 的**全部**字段拼进 SELECT，
    --    于是直接 `Column "give_coupon_template_counts" not found`。
    --    另两列（give_coupon_ids / point_activity_id）同样漏了，一并补上。
    "give_coupon_template_counts" varchar NULL,
    "give_coupon_ids"             varchar NULL,
    "point_activity_id"           bigint  NULL,
    "creator"                 varchar           DEFAULT '',
    "create_time"             datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                 varchar           DEFAULT '',
    "update_time"             datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"                 bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易订单表';

CREATE TABLE IF NOT EXISTS "trade_order_item"
(
    "id"                bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"           bigint   NOT NULL,
    "order_id"          bigint   NOT NULL,
    "cart_id"           int      NULL,
    "spu_id"            bigint   NOT NULL,
    "spu_name"          varchar  NOT NULL,
    "sku_id"            bigint   NOT NULL,
    "properties"        varchar,
    "pic_url"           varchar,
    "count"             int      NOT NULL,
    "comment_status"    boolean  NULL,
    "price"             int      NOT NULL,
    "discount_price"    int      NOT NULL,
    "delivery_price"    int      NULL,
    "adjust_price"      int      NULL,
    "pay_price"         int      NOT NULL,
    "coupon_price"      int      NULL,
    "point_price"       int      NULL,
    "use_point"         int      NULL,
    "give_point"        int      NULL,
    "vip_price"         int      NULL,
    "after_sale_id"     long     NULL,
    "after_sale_status" int      NOT NULL,
    "creator"           varchar           DEFAULT '',
    "create_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar           DEFAULT '',
    "update_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易订单明细表';

CREATE TABLE IF NOT EXISTS "trade_after_sale"
(
    "id"             bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no"             varchar  NOT NULL,
    "status"         int      NOT NULL,
    "type"           int      NOT NULL,
    "way"            int      NOT NULL,
    "user_id"        bigint   NOT NULL,
    "apply_reason"   varchar  NOT NULL,
    "apply_description" varchar,
    "apply_pic_urls" varchar,
    "order_id"       bigint   NOT NULL,
    "order_no"       varchar  NOT NULL,
    "order_item_id"  bigint   NOT NULL,
    "spu_id"         bigint   NOT NULL,
    "spu_name"       varchar  NOT NULL,
    "sku_id"         bigint   NOT NULL,
    "properties"     varchar,
    "pic_url"        varchar,
    "count"          int      NOT NULL,
    "audit_time"     varchar,
    "audit_user_id"  bigint,
    "audit_reason"   varchar,
    "refund_price"   int      NOT NULL,
    "pay_refund_id"  bigint,
    "refund_time"    varchar,
    "logistics_id"   bigint,
    "logistics_no"   varchar,
    "delivery_time"  varchar,
    "receive_time"   varchar,
    "receive_reason" varchar,
    "creator"        varchar           DEFAULT '',
    "create_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar           DEFAULT '',
    "update_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易售后表';

CREATE TABLE IF NOT EXISTS "trade_after_sale_log"
(
    "id"            bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "user_type"     int      NOT NULL,
    "after_sale_id" bigint   NOT NULL,
    "order_id"      bigint   NOT NULL,
    "order_item_id" bigint   NOT NULL,
    "before_status" int,
    "after_status"  int      NOT NULL,
    "content"       varchar  NOT NULL,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易售后日志';

CREATE TABLE IF NOT EXISTS "trade_brokerage_user"
(
    "id"                bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "bind_user_id"      bigint   NOT NULL,
    "bind_user_time"    varchar,
    "brokerage_enabled" bit      NOT NULL,
    "brokerage_time"    varchar,
    "price"             int      NOT NULL,
    "frozen_price"      int      NOT NULL,
    "creator"           varchar           DEFAULT '',
    "create_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar           DEFAULT '',
    "update_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit      NOT NULL DEFAULT FALSE,
    "tenant_id"         bigint   NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT '分销用户';
CREATE TABLE IF NOT EXISTS "trade_brokerage_record"
(
    "id"            bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "biz_id"        varchar  NOT NULL,
    "biz_type"      varchar  NOT NULL,
    "title"         varchar  NOT NULL,
    "price"         int      NOT NULL,
    "total_price"   int      NOT NULL,
    "description"   varchar  NOT NULL,
    "status"        varchar  NOT NULL,
    "frozen_days"   int      NOT NULL,
    "unfreeze_time" varchar,
    "source_user_level" int,
    "source_user_id"    bigint,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金记录';
CREATE TABLE IF NOT EXISTS "trade_brokerage_withdraw"
(
    "id"                  int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"             bigint   NOT NULL,
    "price"               int      NOT NULL,
    "fee_price"           int      NOT NULL,
    "total_price"         int      NOT NULL,
    "type"                varchar  NOT NULL,
    "name"                varchar,
    "account_no"          varchar,
    "bank_name"           varchar,
    "bank_address"        varchar,
    "account_qr_code_url" varchar,
    "status"              varchar  NOT NULL,
    "audit_reason"        varchar,
    "audit_time"          varchar,
    "remark"              varchar,
    "creator"             varchar           DEFAULT '',
    "create_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"             varchar           DEFAULT '',
    "update_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"             bit      NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金提现';

CREATE TABLE IF NOT EXISTS "trade_delivery_express"
(
    "id"          int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code"        varchar  NULL,
    "name"        varchar,
    "logo"        varchar  NULL,
    "sort"        int      NOT NULL,
    "status"      int      NOT NULL,
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '佣金提现';

-- ⚠️ 本模块的测试此前**一张表都没有**（trade-server 没有 src/test/java），
--    下面两张是 006（订单开票）新加的，与 `sql/mysql/007-order-invoice.sql` 一一对应。
--    漏补它们，本模块所有测试类**启动就挂**（不是某个用例失败）。
CREATE TABLE IF NOT EXISTS "trade_order_invoice"
(
    "id"               bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id"         bigint   NOT NULL,
    "order_no"         varchar  NOT NULL,
    "user_id"          bigint   NOT NULL,
    "type"             int      NOT NULL,
    "status"           int      NOT NULL DEFAULT 0,
    "amount"           int      NOT NULL,
    "title_name"       varchar  NOT NULL,
    "tax_no"           varchar,
    "title_address"    varchar,
    "title_phone"      varchar,
    "bank_name"        varchar,
    "invoice_file_url" varchar,
    "issue_time"       datetime,
    "issue_user_id"    bigint,
    "cancel_time"      datetime,
    "creator"          varchar  DEFAULT '',
    "create_time"      datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"          varchar  DEFAULT '',
    "update_time"      datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"          bit      NOT NULL DEFAULT FALSE,
    "tenant_id"        bigint   NOT NULL DEFAULT '0',
    -- H2 里不建 KEY（本文件既有表格一律不建索引），但**唯一约束保留**：
    -- 「一个订单最多一条申请」是 FR-160，服务层与数据库各挡一道，测试要能验到库这一道。
    CONSTRAINT "uk_order_id" UNIQUE ("order_id"),
    PRIMARY KEY ("id")
) COMMENT '交易订单开票申请';

CREATE TABLE IF NOT EXISTS "trade_invoice_title"
(
    "id"             bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"        bigint   NOT NULL,
    "title_name"     varchar  NOT NULL,
    "tax_no"         varchar,
    "title_address"  varchar,
    "title_phone"    varchar,
    "bank_name"      varchar,
    "default_status" bit      NOT NULL DEFAULT FALSE,
    "creator"        varchar  DEFAULT '',
    "create_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar  DEFAULT '',
    "update_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT '会员发票抬头';
